'use strict';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS users (
    user_id INTEGER PRIMARY KEY AUTOINCREMENT,
    google_id TEXT,
    username TEXT NOT NULL UNIQUE,
    email TEXT,
    password TEXT,
    email_verified INTEGER NOT NULL DEFAULT 0,
    profile_pic TEXT,
