    recipe: '["boil","serve"]', ingredients: '[]', date: '2026-01-01' },
  { recipe_id: 102, user_id: 2, name: "Bob's Seed Stew", info: 'seeded',
    recipe: '["simmer"]', ingredients: '[]', date: '2026-01-01' },
