// the fixture itself. alice likes recipe 102, so 102 carries likes = 1.
const LIKES = [{ like_id: 1, recipe_id: 102, user_id: 1, rating: 1 }];
const RANKING = [
  { recipe_id: 101, likes: 0, dislikes: 0, views: 0 },
  { recipe_id: 102, likes: 1, dislikes: 0, views: 0 },
];
const COMMENTS = [
